from collections import deque
class Solution:
    def minCost(self, m, n):
        if m == 1 and n == 1: return 1
        dq = deque([(0, 0, 1, 1)])
        seen = {(0, 0, 1)}
        while dq:
            r, c, cost, t = dq.popleft()
            dirs = ((0, 1), (1, 0)) if t % 2 else ((0, -1), (-1, 0))
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    ncost = cost + (nr + 1) * (nc + 1)
                    if nr == m - 1 and nc == n - 1: return ncost
                    key = (nr, nc, (t + 1) % 2)
                    if key not in seen:
                        seen.add(key)
                        dq.append((nr, nc, ncost, t + 1))
        return -1

