class Solution {
public:
    int minCost(int m, int n) {
        if (m == 1 && n == 1) return 1;
        queue<array<int,4>> q;
        q.push({0, 0, 1, 1});
        set<array<int,3>> seen;
        seen.insert({0, 0, 1});
        while (!q.empty()) {
            auto cur = q.front(); q.pop();
            int r = cur[0], c = cur[1], cost = cur[2], t = cur[3];
            int dd[2][2];
            if (t % 2 == 1) { dd[0][0]=0; dd[0][1]=1; dd[1][0]=1; dd[1][1]=0; }
            else { dd[0][0]=0; dd[0][1]=-1; dd[1][0]=-1; dd[1][1]=0; }
            for (int d = 0; d < 2; d++) {
                int nr = r + dd[d][0], nc = c + dd[d][1];
                if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
                int ncost = cost + (nr + 1) * (nc + 1);
                if (nr == m - 1 && nc == n - 1) return ncost;
                array<int,3> k = {nr, nc, (t + 1) % 2};
                if (seen.insert(k).second) q.push({nr, nc, ncost, t + 1});
            }
        }
        return -1;
    }
};

