class Solution {
    public int minCost(int m, int n) {
        if (m == 1 && n == 1) return 1;
        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0, 1, 1});
        Set<String> seen = new HashSet<>();
        seen.add("0,0,1");
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], cost = cur[2], t = cur[3];
            int[][] dd = (t % 2 == 1) ? new int[][]{{0,1},{1,0}} : new int[][]{{0,-1},{-1,0}};
            for (int[] d : dd) {
                int nr = r + d[0], nc = c + d[1];
                if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
                int ncost = cost + (nr + 1) * (nc + 1);
                if (nr == m - 1 && nc == n - 1) return ncost;
                String k = nr + "," + nc + "," + ((t + 1) % 2);
                if (seen.add(k)) q.add(new int[]{nr, nc, ncost, t + 1});
            }
        }
        return -1;
    }
}

