var minCost = function(m, n) {
    if (m === 1 && n === 1) return 1;
    const q = [[0, 0, 1, 1]];
    const seen = new Set(['0,0,1']);
    for (let h = 0; h < q.length; h++) {
        const [r, c, cost, t] = q[h];
        const dirs = t % 2 === 1 ? [[0,1],[1,0]] : [[0,-1],[-1,0]];
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
            const ncost = cost + (nr + 1) * (nc + 1);
            if (nr === m - 1 && nc === n - 1) return ncost;
            const k = nr + ',' + nc + ',' + ((t + 1) % 2);
            if (!seen.has(k)) { seen.add(k); q.push([nr, nc, ncost, t + 1]); }
        }
    }
    return -1;
};
